export interface ChatMessage {
  role: "system" | "user";
  content: string;
}

export interface CompleteOptions {
  responseFormat?: "json_object" | "text";
  signal?: AbortSignal;
}

export class CancelledError extends Error {
  constructor(message = "Operation cancelled by user") {
