function fakeExplanation(overrides: Partial<Explanation> = {}): Explanation {
  return {
    segmentId: "seg-abc",
    summary: "A 20+char valid summary that explains what the block does in detail.",
    pointsToConsider: { assumptions: [], dangers: [], sideEffects: [] },
    concepts: [],
    renderState: "done",
    ...overrides,
