            const content = obj?.choices?.[0]?.delta?.content;
            if (typeof content === "string" && content.length > 0) {
              yield { chunk: content, bytes: totalBytes };
            }
          } catch {
            // Ignore malformed partial frames; SSE payloads are per-frame JSON.
          }
        }
      }
    }
  } finally {
    try {
      await reader.cancel();
    } catch { /* ignore */ }
  }
}
