      name: (c as any).name,
      briefExplainer: (c as any).briefExplainer,
      relevance: (c as any).relevance,
    });
  }

  return { summary: obj.summary, pointsToConsider, concepts };
}

function filterPtcItems(x: unknown): string[] {
  if (!Array.isArray(x)) return [];
