  private findUri(segmentId: string): vscode.Uri | undefined {
    for (const uri of this.allStoreUris()) {
      const segs = this.segStore.get(uri) ?? [];
      if (segs.some(s => s.id === segmentId)) return uri;
    }
    return undefined;
