    expStore.set("seg-1", "groq", "v1", fakeExplanation("seg-1", "streaming"));

    const controller = new CodeWalkCommentController(segStore, expStore, {
      adapter: explodingAdapter(),
      promptsDir: "",
      preset: "groq",
      promptVersion: "v1",
